diff --git a/test/signup.test.ts b/test/signup.test.ts
--- /dev/null
+++ b/test/signup.test.ts
@@ -0,0 +1,50 @@
+import { test, beforeEach } from "node:test";
+import assert from "node:assert/strict";
+import { app } from "../src/api/routes.ts";
+import { resetUsers } from "../src/auth/users.ts";
+import { resetSessions } from "../src/auth/session.ts";
+
+const signup = (body: unknown) => app({ method: "POST", path: "/api/signup", body, headers: {} });
+
+beforeEach(() => {
+  resetUsers();
+  resetSessions();
+});
+
+test("signup creates a public user and a token usable for /api/me", async () => {
+  const response = await signup({ email: "ADA@example.com", name: "Ada", password: "correct horse" });
+  assert.equal(response.status, 201);
+  const { token, user } = response.body as { token: string; user: { id: string; email: string; name: string } };
+  assert.ok(token);
+  assert.match(user.id, /^u_/);
+  assert.deepEqual(user, { id: user.id, email: "ada@example.com", name: "Ada" });
+
+  const me = await app({ method: "GET", path: "/api/me", headers: { authorization: `Bearer ${token}` } });
+  assert.equal(me.status, 200);
+  assert.deepEqual(me.body, user);
+});
+
+test("signup rejects missing fields", async () => {
+  for (const body of [null, {}, { email: "ada@example.com", name: "Ada" }, { email: "ada@example.com", password: "correct horse" }, { name: "Ada", password: "correct horse" }]) {
+    const response = await signup(body);
+    assert.equal(response.status, 400);
+    assert.deepEqual(response.body, { error: "email, name and password are required" });
+  }
+});
+
+test("signup returns UserError messages for invalid email and short password", async () => {
+  const invalidEmail = await signup({ email: "invalid", name: "Ada", password: "correct horse" });
+  assert.equal(invalidEmail.status, 400);
+  assert.deepEqual(invalidEmail.body, { error: "invalid email" });
+
+  const shortPassword = await signup({ email: "ada@example.com", name: "Ada", password: "short" });
+  assert.equal(shortPassword.status, 400);
+  assert.deepEqual(shortPassword.body, { error: "password must be at least 8 characters" });
+});
+
+test("signup rejects a duplicate email case-insensitively", async () => {
+  await signup({ email: "ada@example.com", name: "Ada", password: "correct horse" });
+  const response = await signup({ email: "ADA@example.com", name: "Another Ada", password: "correct horse" });
+  assert.equal(response.status, 400);
+  assert.deepEqual(response.body, { error: "email already registered" });
+});

